--[=[
    @class IPlayerScopeCancellationToken
    玩家作用域取消令牌接口
]=]

export type IPlayerScopeCancellationToken = {
    --- 是否已启动作用域
    isScopeStarted: boolean,

    --- 是否已离开玩家
    isPlayerRemoved: boolean,

    --- 如果玩家已经离开，并且作用域未启动，则返回 true
    IsCancelled: (self: IPlayerScopeCancellationToken) -> boolean
}

return {}